-- student logins through the real provisioning function, acting as the seed admin
select set_config('request.jwt.claim.sub', '3e88b18e-6743-5439-8794-3b89d3111fee', true),
       set_config('request.jwt.claims', '{"sub":"3e88b18e-6743-5439-8794-3b89d3111fee","role":"authenticated"}', true);
select count(public.provision_student_login(s.id, '1234')) as student_logins_created
from public.students s
where s.student_code like 'TEST-%'
  and not exists (select 1 from public.profiles p where p.student_id = s.id);
select set_config('request.jwt.claim.sub', '', true), set_config('request.jwt.claims', '', true);

-- is_test_data exists only once db/017 is applied
do $$
begin
  if exists (select 1 from information_schema.columns
             where table_schema = 'public' and table_name = 'students' and column_name = 'is_test_data') then
    execute $q$update public.students set is_test_data = true
               where student_code like 'TEST-%' and not is_test_data$q$;
    execute $q$update public.profiles p set is_test_data = true
               where not p.is_test_data and (p.id in (select id from auth.users where email like '%@seed.school.invalid')
                  or p.student_id in (select id from public.students where student_code like 'TEST-%'))$q$;
  end if;
end $$;

commit;

-- What you should see: 656 students, 22 classes, 687 logins.
select (select count(*) from public.students where student_code like 'TEST-%') as test_students,
       (select count(*) from public.classes where name like 'TEST %') as test_classes,
       (select count(*) from public.profiles p join auth.users u on u.id = p.id
         where u.email like '%@seed.school.invalid'
            or p.student_id in (select id from public.students where student_code like 'TEST-%')) as test_logins;
